"""
Boolean value evaluation over the powerset algebra of generic objects,
together with the realization test  (S,g) ⊨ p  ⟺  g ∈ ⟦p⟧_S.

The Boolean algebra is B = P(G) with G = {0,1}^m the space of switch settings
(generic objects).  An element of B is an integer bitmask of width 2^m: bit k is
set iff the k-th generic object belongs to the set.  All Boolean operations are
bitwise, so ⟦p⟧_S costs O(|p|) word operations for small m and
O(|p| · 2^m / w) in general, where w is the machine word size.
"""

from __future__ import annotations

from itertools import product
from typing import Dict, FrozenSet, List, Sequence, Tuple

Atom = Tuple[str, int]      # ("btn", i) or ("sw", j)
Formula = Tuple             # ("atom", Atom) | ("fls",) | ("imp", Formula, Formula)

FLS: Formula = ("fls",)


def atom(kind: str, index: int) -> Formula:
    return ("atom", (kind, index))


def imp(p: Formula, q: Formula) -> Formula:
    return ("imp", p, q)


def neg(p: Formula) -> Formula:
    return imp(p, FLS)


def conj(p: Formula, q: Formula) -> Formula:
    return neg(imp(p, neg(q)))


def disj(p: Formula, q: Formula) -> Formula:
    return imp(neg(p), q)


def top_mask(m: int) -> int:
    """⊤ = the whole space of generic objects, as a bitmask of width 2^m."""
    return (1 << (1 << m)) - 1


def generic_objects(m: int) -> List[Tuple[int, ...]]:
    """The 2^m switch settings, in the order used for bit positions."""
    return [tuple(reversed(bits)) for bits in product((0, 1), repeat=m)]


def generic_index(g: Sequence[int]) -> int:
    """Bit position of the generic object g."""
    return sum(bit << k for k, bit in enumerate(g))


def make_assignment(stage: FrozenSet[int], n: int, m: int) -> Dict[Atom, int]:
    """
    Stage-`stage` assignment: a pushed button gets ⊤, an unpushed one ⊥, and
    switch j gets the set of generic objects that turn it on.
    """
    full = top_mask(m)
    assign: Dict[Atom, int] = {("btn", i): (full if i in stage else 0)
                               for i in range(n)}
    for j in range(m):
        mask = 0
        for idx, g in enumerate(generic_objects(m)):
            if g[j] == 1:
                mask |= 1 << idx
        assign[("sw", j)] = mask
    return assign


def bval(p: Formula, assign: Dict[Atom, int], m: int) -> int:
    """Boolean value ⟦p⟧ of p under the given assignment."""
    if p[0] == "fls":
        return 0
    if p[0] == "atom":
        return assign[p[1]]
    a = bval(p[1], assign, m)
    b = bval(p[2], assign, m)
    return (top_mask(m) & ~a) | b          # a ⇒ b  =  aᶜ ∨ b


def csat(stage: FrozenSet[int], g: Sequence[int], p: Formula) -> bool:
    """Two-valued truth of p at the control world (stage, g)."""
    if p[0] == "fls":
        return False
    if p[0] == "atom":
        kind, i = p[1]
        return (i in stage) if kind == "btn" else (g[i] == 1)
    return (not csat(stage, g, p[1])) or csat(stage, g, p[2])


def realization_holds(p: Formula, stage: FrozenSet[int], n: int, m: int) -> bool:
    """Verify  (S,g) ⊨ p  ⟺  g ∈ ⟦p⟧_S  for every generic object g."""
    value = bval(p, make_assignment(stage, n, m), m)
    return all(
        csat(stage, g, p) == bool(value >> generic_index(g) & 1)
        for g in generic_objects(m)
    )


if __name__ == "__main__":
    n, m = 2, 2
    ch = atom("sw", 0)
    for stage in (frozenset(), frozenset({0}), frozenset({0, 1})):
        assign = make_assignment(stage, n, m)
        print("stage", set(stage),
              " [[b0]] =", bin(bval(atom("btn", 0), assign, m)),
              " [[CH]] =", bin(bval(ch, assign, m)),
              " realization ok:", realization_holds(conj(atom("btn", 0), ch),
                                                    stage, n, m))

"""
Schematic modal validity checking on a finite control frame.

A modal *schema* (T, 4, .2, 5, B, .3) is valid on a finite frame iff it holds
for every predicate substituted for its schematic letters.  On a frame with |W|
worlds there are 2^|W| predicates per letter, so a one-letter schema costs
O(2^|W| · |W|^2) and a two-letter schema O(4^|W| · |W|^2).  This is exponential,
but immediate for the small frames that carry the canonical countermodels
(n = m = 1 for the failure of 5 and B, n = 2 for the failure of .3).

The checker confirms:  T, 4 and .2 are valid on every control frame (so the
frame is an S4.2 frame);  5 and B fail as soon as there is one button;  .3 fails
as soon as there are two independent buttons.
"""

from __future__ import annotations

from itertools import combinations, product
from typing import Callable, FrozenSet, Iterator, List, Optional, Tuple

World = Tuple[FrozenSet[int], Tuple[int, ...]]
Pred = Callable[[World], bool]


def worlds(n: int, m: int) -> List[World]:
    stages = [frozenset(c) for r in range(n + 1) for c in combinations(range(n), r)]
    settings = [tuple(reversed(b)) for b in product((0, 1), repeat=m)]
    return [(S, g) for S in stages for g in settings]


def accessible(w: World, v: World) -> bool:
    return w[0] <= v[0]


def box(ws: List[World], P: Pred) -> Pred:
    return lambda w: all(P(v) for v in ws if accessible(w, v))


def dia(ws: List[World], P: Pred) -> Pred:
    return lambda w: any(P(v) for v in ws if accessible(w, v))


def gdia(ws: List[World], P: Pred) -> Pred:
    """Ground possibility: 'true in some universe of which this is an extension'."""
    return lambda w: any(P(v) for v in ws if accessible(v, w))


def predicates(ws: List[World]) -> Iterator[Pred]:
    """All 2^|W| predicates on the frame."""
    index = {w: i for i, w in enumerate(ws)}
    for mask in range(1 << len(ws)):
        yield (lambda mask=mask: (lambda w: bool(mask >> index[w] & 1)))()


def check_schema(n: int, m: int, name: str) -> Tuple[bool, Optional[str]]:
    """
    Test a named schema on the n-button, m-switch frame.  Returns (valid,
    witness) where witness describes a refuting instance when valid is False.
    """
    ws = worlds(n, m)
    if name in ("T", "4", ".2", "5", "B", "tense"):
        for P in predicates(ws):
            for w in ws:
                if name == "T":
                    ok = (not box(ws, P)(w)) or P(w)
                elif name == "4":
                    ok = (not box(ws, P)(w)) or box(ws, box(ws, P))(w)
                elif name == ".2":
                    ok = (not dia(ws, box(ws, P))(w)) or box(ws, dia(ws, P))(w)
                elif name == "5":
                    ok = (not dia(ws, P)(w)) or box(ws, dia(ws, P))(w)
                elif name == "B":
                    ok = (not P(w)) or box(ws, dia(ws, P))(w)
                else:  # mixed tense axiom  p -> box gdia p
                    ok = (not P(w)) or box(ws, gdia(ws, P))(w)
                if not ok:
                    ext = {w2 for w2 in ws if P(w2)}
                    return False, "refuted at %s by predicate true on %d worlds" % (
                        (sorted(w[0]), w[1]), len(ext))
        return True, None
    if name == ".3":
        for P in predicates(ws):
            for Q in predicates(ws):
                for w in ws:
                    left = box(ws, lambda v: (not box(ws, P)(v)) or Q(v))(w)
                    right = box(ws, lambda v: (not box(ws, Q)(v)) or P(v))(w)
                    if not (left or right):
                        return False, "refuted at %s" % ((sorted(w[0]), w[1]),)
        return True, None
    raise ValueError("unknown schema " + name)


if __name__ == "__main__":
    for (n, m) in [(1, 1), (2, 0)]:
        print("frame with %d button(s), %d switch(es), %d worlds"
              % (n, m, len(worlds(n, m))))
        for name in ["T", "4", ".2", "5", "B", "tense"] + ([".3"] if n >= 2 else []):
            valid, witness = check_schema(n, m, name)
            print("   %-6s valid: %-5s %s" % (name, valid, witness or ""))

"""
Deciding multiverse invariance, and the two-sided branch-preservation criterion.

INVARIANCE.  An assertion is invariant along the button order -- equivalently,
preserved both by passing to forcing extensions and by passing back down to
grounds -- iff its truth value depends only on the switch setting.  The
Invariant Fragment Theorem says this holds iff the assertion is equivalent to a
button-free one, and supplies a canonical witness: substitute ⊥ for every button
atom.  The normalization is O(|p|); confirming agreement over all worlds is
O(|p| · 2^(n+m)).

BRANCH PRESERVATION.  A background condition b survives into a p-branch and a
¬p-branch of one and the same Boolean-valued universe iff
    b ∧ ⟦p⟧ ≠ ⊥   and   b ∧ ⟦p⟧ᶜ ≠ ⊥,
a necessary and sufficient condition testable in two word operations.
"""

from __future__ import annotations

from itertools import combinations, product
from typing import Dict, FrozenSet, List, Sequence, Tuple

Atom = Tuple[str, int]
Formula = Tuple

FLS: Formula = ("fls",)


def atom(kind: str, index: int) -> Formula:
    return ("atom", (kind, index))


def imp(p: Formula, q: Formula) -> Formula:
    return ("imp", p, q)


def neg(p: Formula) -> Formula:
    return imp(p, FLS)


def conj(p: Formula, q: Formula) -> Formula:
    return neg(imp(p, neg(q)))


def show(p: Formula) -> str:
    if p[0] == "fls":
        return "⊥"
    if p[0] == "atom":
        kind, i = p[1]
        return ("b%d" % i) if kind == "btn" else ("s%d" % i)
    if p[2] == FLS:
        return "¬" + show(p[1])
    return "(%s → %s)" % (show(p[1]), show(p[2]))


def stages(n: int) -> List[FrozenSet[int]]:
    return [frozenset(c) for r in range(n + 1) for c in combinations(range(n), r)]


def settings(m: int) -> List[Tuple[int, ...]]:
    return [tuple(reversed(b)) for b in product((0, 1), repeat=m)]


def csat(S: FrozenSet[int], g: Sequence[int], p: Formula) -> bool:
    if p[0] == "fls":
        return False
    if p[0] == "atom":
        kind, i = p[1]
        return (i in S) if kind == "btn" else (g[i] == 1)
    return (not csat(S, g, p[1])) or csat(S, g, p[2])


def button_free_normal_form(p: Formula) -> Formula:
    """Substitute ⊥ for every button atom: the canonical button-free candidate."""
    if p[0] == "fls":
        return p
    if p[0] == "atom":
        return FLS if p[1][0] == "btn" else p
    return imp(button_free_normal_form(p[1]), button_free_normal_form(p[2]))


def is_invariant(p: Formula, n: int, m: int) -> bool:
    """Exhaustive test: does the truth value depend only on the switch setting?"""
    for g in settings(m):
        if len({csat(S, g, p) for S in stages(n)}) > 1:
            return False
    return True


def decide_invariance(p: Formula, n: int, m: int) -> Tuple[bool, Formula]:
    """
    Decide invariance and return (verdict, witness).  When the verdict is True
    the witness is a button-free assertion equivalent to p at every world.
    """
    nf = button_free_normal_form(p)
    agrees = all(
        csat(S, g, p) == csat(S, g, nf) for S in stages(n) for g in settings(m)
    )
    return agrees, nf


def top_mask(m: int) -> int:
    return (1 << (1 << m)) - 1


def survives_both_branches(background: int, value: int, m: int) -> bool:
    """The exact two-sided preservation criterion."""
    full = top_mask(m)
    return (background & value) != 0 and (background & full & ~value) != 0


if __name__ == "__main__":
    n, m = 2, 2
    tests = [
        atom("sw", 0),
        imp(atom("sw", 0), atom("sw", 1)),
        atom("btn", 0),
        imp(atom("btn", 0), atom("btn", 0)),
        conj(atom("btn", 0), atom("sw", 0)),
    ]
    for p in tests:
        verdict, witness = decide_invariance(p, n, m)
        assert verdict == is_invariant(p, n, m)
        print("%-22s invariant: %-5s  button-free witness: %s"
              % (show(p), verdict, show(witness) if verdict else "-"))

    # branch preservation, with CH the first switch at stage {0}
    ch_value = 0
    for idx, g in enumerate(settings(m)):
        if g[0] == 1:
            ch_value |= 1 << idx
    print("button background ⊤ survives both CH branches:",
          survives_both_branches(top_mask(m), ch_value, m))
    print("switch background ⟦CH⟧ survives both CH branches:",
          survives_both_branches(ch_value, ch_value, m))
